<script setup lang="ts">
import { Palette as PaletteIcon, Save, ImagePlus, SlidersHorizontal, ArrowRight } from 'lucide-vue-next'
import { normalizePalette, paletteSchema, usedColorTokens, paletteEntries, resolveColor, prepareComponent, type ComponentData, type Palette, type Resource, type Asset } from '@qinbian/shared'
const props=defineProps<{data:ComponentData;themeSetId?:string}>(),emit=defineEmits<{update:[data:ComponentData]}>(),ctx=useQinbian()
const cards=ref<Resource[]>([]),cardsOpen=ref(false),editing=ref(false),draft=ref<Palette>(normalizePalette(props.data.palette)),token=ref(''),imageField=ref('')
const palette=computed(()=>normalizePalette(props.data.palette,ctx.themes.value.find(t=>t.id===props.themeSetId)?.tokens))
const tokens=computed(()=>usedColorTokens(props.data.html||'')),entries=computed(()=>paletteEntries(palette.value))
const fields=computed(()=>props.data.fields||[])
function update(patch:Partial<ComponentData>){emit('update',prepareComponent({...props.data,...patch},palette.value))}
function beginEdit(){draft.value=structuredClone(toRaw(palette.value));editing.value=true}
function setValue(id:string,value:string|number){update({values:{...props.data.values,[id]:value}})}
function mappingLabel(t:string){const mapped=props.data.colorMappings?.[t]||t;return entries.value.find(e=>e.token===mapped)?.label||mapped}
function changeMapping(choice:{token?:string;value:string}){const mappings={...props.data.colorMappings};if(choice.token===token.value)delete mappings[token.value];else mappings[token.value]=choice.token||choice.value;update({colorMappings:mappings});token.value=''}
function applyPalette(p:Palette){if(!paletteSchema.safeParse(p).success){ctx.notify('请为每个颜色填写名称和有效色值，保留3至6个颜色',true);return}const mappings={...props.data.colorMappings};for(const t of tokens.value)if(!paletteEntries(p).some(e=>e.token===t))mappings[t]=resolveColor(t,palette.value,mappings);update({palette:p,colorMappings:mappings});cardsOpen.value=false;editing.value=false}
async function pickCard(){try{cards.value=await apiFetch<Resource[]>('/api/resources',{query:{kind:'palette'}});cardsOpen.value=true}catch(e){ctx.error(e)}}
async function saveCard(){try{await apiFetch('/api/resources',{method:'POST',body:{kind:'palette',themeSetId:'mine',name:palette.value.name||'我的配色',description:'从组件中收录的配色，可在其他套组与组件中复用。',category:'配色卡',tags:['配色'],data:{palette:palette.value}}});ctx.notify('配色已收进资源库')}catch(e){ctx.error(e)}}
function chooseImage(a:Asset){setValue(imageField.value,`/api/assets/${a.id}/file`);imageField.value=''}
</script>
<template><section class="component-bindings"><div class="bindings-heading"><h4><PaletteIcon :size="14"/>配色与映射</h4><button class="text-button" @click="beginEdit">调整配色</button></div><div class="binding-palette-strip"><i v-for="c in palette.colors" :key="c.id" :style="{background:c.regular}" :title="c.name"/></div><div class="bindings-actions"><button class="text-button" @click="pickCard">选用配色卡</button><button class="text-button" @click="saveCard"><Save :size="12"/>收为配色卡</button></div><div v-if="tokens.length" class="mapping-list"><button v-for="t in tokens" :key="t" @click="token=t"><span><i :style="{background:resolveColor(t,palette,data.colorMappings)}"/><span>{{entries.find(e=>e.token===t)?.label||t}}<code>{{t}}</code></span></span><span class="mapping-target">{{mappingLabel(t)}}<ArrowRight :size="11"/></span></button></div><p v-else class="small muted">当前元素使用自定义颜色。新生成的主题色会显示在这里供映射。</p><div v-if="fields.length" class="data-field-list"><h4>可修改内容与数据</h4><label v-for="f in fields" :key="f.id"><span>{{f.label}}<small>{{f.id}}</small></span><template v-if="f.type==='text'"><textarea :value="data.values?.[f.id]??f.default" rows="2" @input="setValue(f.id,($event.target as HTMLTextAreaElement).value)"/></template><template v-else-if="f.type==='number'"><input :value="data.values?.[f.id]??f.default" type="number" :min="f.min" :max="f.max" :step="f.step||'any'" @input="setValue(f.id,Number(($event.target as HTMLInputElement).value))"><small v-if="f.suffix">{{f.suffix}}</small></template><template v-else-if="f.type==='image'"><button class="btn" @click="imageField=f.id"><ImagePlus :size="14"/>选择图片</button></template><template v-else><output>由其他数值自动计算</output></template></label></div>
 <ColorPicker v-if="token" :title="'修改映射 '+token" :palette="palette" :mappings="data.colorMappings" @close="token=''" @choose="changeMapping"/>
 <UiModal v-if="editing" title="组件配色" subtitle="颜色名称可以自由修改，代号保持稳定。" @close="editing=false"><PaletteEditor v-model="draft" :used-tokens="tokens"/><div class="modal-actions"><button class="btn primary" @click="applyPalette(draft)">应用组件配色</button></div></UiModal>
 <UiModal v-if="cardsOpen" title="选择配色卡" subtitle="选用后将配色留在当前组件中，其他文章不会受到影响。" wide @close="cardsOpen=false"><div class="palette-picker-grid"><button v-for="card in cards" :key="card.id" @click="applyPalette(normalizePalette(card.data.palette))"><h3>{{card.name}}</h3><PaletteSwatches :palette="card.data.palette" compact/></button></div><p v-if="!cards.length" class="muted small">先到资源库创建或生成一张配色卡。</p></UiModal>
 <AssetPicker v-if="imageField" @close="imageField=''" @select="chooseImage"/>
 </section></template>
